impl Set[T]:
    fn new() -> Set[T]:
        return Set([])

    fn add(inout self, item: T):
        if not self.contains(item):
            self.items.append(item)

    fn contains(self, item: T) -> bool:
        for i in self.items:
            if i == item:
                return true
        return false

    fn to_list(self) -> [T]:
        return self.items

