        if num <= 1:
            return false
        if num <= 3:
            return true
        if num % 2 == 0 or num % 3 == 0:
            return false
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return false
            i += 6
        return true

    fn fib(n: int) -> int:
        if n <= 1:
            return n
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

