fn largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    fn is_prime(x: int) -> bool:
        if x <= 1:
            return false
        if x <= 3:
            return true
        if x % 2 == 0 or x % 3 == 0:
            return false
        i: int = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return false
            i += 6
        return true

    var max_prime: int = -1
    while n % 2 == 0:
        max_prime = 2
        n = n // 2

    for i in range(3, int(sqrt(n)) + 1, 2):
        while n % i == 0:
            max_prime = i
            n = n // i

    if n > 2:
        max_prime = n

    return max_prime
