    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    fn is_prime(x: int) -> bool:
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    var max_prime = 1
    var i = 2
    while i * i <= n:
        if n % i == 0:
            if is_prime(i):
                max_prime = i
            if is_prime(n // i):
                max_prime = n // i
        i += 1
    return max_prime
