fn max_sum(arr: [int]) -> int:
    n = len(arr)
    if n == 0:
        return 0

    inc = [0] * n
    dec = [0] * n

    for i in range(n):
        inc[i] = arr[i]
        dec[i] = arr[i]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum
