fn comb_sort(nums: [int]) -> [int]:
    var gap = len(nums)
    var shrink_factor = 1.3
    var sorted = false

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted = true

        var i = 0
        while i + gap < len(nums):
            if nums[i] > nums[i + gap]:
                nums.swap(i, i + gap)
                sorted = false
            i += 1

    return nums
