type Heap[T] = Heap(items: [T])

impl Heap[T]:
    fn new() -> Heap[T]:
        return Heap(items: [])

    fn push(inout self, item: T):
        self.items.append(item)
        self.heapify_up(len(self.items) - 1)

    fn pop_min(inout self) -> T?:
        if len(self.items) == 0:
            return None
        if len(self.items) == 1:
            return self.items.pop()
        min_item = self.items[0]
        self.items[0] = self.items.pop()
        self.heapify_down(0)
        return min_item

    fn heapify_up(inout self, index: int):
        while index > 0:
            parent_index = (index - 1) // 2
            if self.items[index] < self.items[parent_index]:
                self.items[index], self.items[parent_index] = self.items[parent_index], self.items[index]
                index = parent_index
            else:
                break

    fn heapify_down(inout self, index: int):
        n = len(self.items)
        while True:
            left_child_index = 2 * index + 1
            right_child_index = 2 * index + 2
            smallest = index

            if left_child_index < n and self.items[left_child_index] < self.items[smallest]:
                smallest = left_child_index

            if right_child_index < n and self.items[right_child_index] < self.items[smallest]:
                smallest = right_child_index

            if smallest != index:
                self.items[index], self.items[smallest] = self.items[smallest], self.items[index]
                index = smallest
            else:
                break

fn check_min_heap(arr: [int]) -> bool:
    var heap = Heap[int]()
    for item in arr:
        heap.push(item)
    for i in range(len(arr)):
        if heap.pop_min() != arr[i]:
            return false
    return true
